int pd_font_cjk_slot(uint32_t codepoint) {
    int low = 0;
    int high = PD_CJK_GLYPHS - 1;
    while (low <= high) {
        const int middle = (low + high) / 2;
        const uint32_t value = kCjkCodepoints[middle];
        if (value == codepoint) return middle;
        if (value < codepoint)
            low = middle + 1;
        else
            high = middle - 1;
    }
    return -1;
}
